WITH exploded AS (SELECT id, service, host, log_ts, level, latency_ms, status_code, key, v FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS key, v), unpacked AS (SELECT id, host, log_ts, latency_ms, status_code, key, v, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 8) != 0 AS INT) AS has_fault FROM exploded WHERE log_ts < '2024-07-18'), base AS (SELECT id, log_ts, latency_ms, status_code, key, v, HOUR(log_ts) AS log_ts_hour FROM unpacked WHERE log_ts >= DATE '2025-06-01' AND latency_ms != 2039), filtered AS (SELECT *, ROUND(status_code, 0) AS status_code_rounded FROM base WHERE log_ts_hour != 80) SELECT CASE WHEN status_code_rounded >= 72 THEN 'HIGH' ELSE 'LOW' END AS status_code_rounded_tier, key, SORT_ARRAY(COLLECT_SET(key)) AS key_list, COUNT(*) AS row_count, ROUND(SUM(status_code_rounded) / NULLIF(COUNT(CASE WHEN key = 'region' THEN 1 END), 0), 2) AS status_code_rounded_per_region, RANK() OVER (PARTITION BY CASE WHEN status_code_rounded >= 72 THEN 'HIGH' ELSE 'LOW' END ORDER BY COUNT(*) DESC) AS row_count_rank FROM filtered GROUP BY status_code_rounded_tier, key;
